{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    nodes = case.get('nodes')
    core_distance = case.get('core_distance')
    distances = case.get('distances')
    if nodes is None or core_distance is None or distances is None:
        raise ValueError('missing required fields: nodes, core_distance, distances')
    if not isinstance(nodes, list) or not isinstance(core_distance, dict) or not isinstance(distances, list):
        raise ValueError('invalid field types')
    n = len(nodes)
    if n == 0:
        return {'edges': [], 'total_weight': 0.0}
    # Build edges with mutual reachability, canonicalize endpoints
    edges = []
    for triple in distances:
        if not isinstance(triple, list) or len(triple) != 3:
            raise ValueError('each distance entry must be a list of three elements')
        u, v, d = triple
        if u == v:
            continue
        # canonical order: u < v (string compare)
        if u > v:
            u, v = v, u
        w = max(core_distance[u], core_distance[v], d)
        edges.append((w, u, v))
    # Sort deterministically: weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find (Disjoint Set Union) with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append({'source': u, 'target': v, 'weight': w})
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected; cannot form MST')
    return {'edges': mst_edges, 'total_weight': total_weight}"}
